#!/usr/bin/env bash
set -Eeuo pipefail
SCRIPT_DIR="$(cd -P "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)"; VMS_DIR="$(cd -P "$SCRIPT_DIR/.." && pwd -P)"; source "$VMS_DIR/lib/comum.sh"
CONFIG=""; while (($#)); do case "$1" in --config) CONFIG="${2:-}"; shift 2;; --self-test) ce_port_valid 3306 && ! ce_port_valid 70000 && echo 'SELF_TEST_INTEGRACAO=APROVADO'; exit;; *) exit 64;; esac; done
[[ -r "$CONFIG" ]] || exit 64; [[ "$(hostname)" == conectaeduca-dmz ]] || { echo "ERRO: execute na CE-UBUNTU-DMZ" >&2; exit 1; }; DB="$(ce_cfg_required CONECTAEDUCA_DB_HOST "$CONFIG")"; DP="$(ce_cfg_get CONECTAEDUCA_DB_PORT "$CONFIG")"; DP="${DP:-3306}"; APP="$(ce_cfg_required CONECTAEDUCA_APP_URL "$CONFIG")"; STAMP="$(date +%Y%m%d-%H%M%S)"; OUT="$HOME/Downloads/conectaeduca-checkpoint-integracao-vms-$STAMP.txt"; : >"$OUT"; ce_set_report "$OUT"; ce_section 'ConectaEduca / integração DMZ -> pfSense -> interna'
if timeout 5 bash -c "</dev/tcp/$DB/$DP" 2>/dev/null; then ce_ok "TCP_DB=$DB:$DP acessível"; else ce_fail "TCP_DB=$DB:$DP inacessível"; fi; ROUTE="$(ip route get "$DB" 2>/dev/null | head -1 || true)"; ce_emit "ROTA_DB=${ROUTE:-INDETERMINADA}"; if curl -kfsS --max-time 8 "$APP/healthz" >/dev/null 2>&1 || curl -kfsS --max-time 8 "$APP/" >/dev/null 2>&1; then ce_ok 'HTTPS_APP respondeu'; else ce_fail 'HTTPS_APP não respondeu'; fi; ce_emit 'OPENBAO_CROSS_VM=NAO_REQUERIDO_NA_FASE1'; ce_emit "FAILURES=$CE_FAILURES"; ce_emit "ARQUIVO_SAIDA=$OUT"; (( CE_FAILURES==0 )) && { ce_emit 'CHECKPOINT_INTEGRACAO=APROVADO'; exit 0; }; ce_emit 'CHECKPOINT_INTEGRACAO=REPROVADO'; exit 1
